import { mulberry32 } from '../combat/damage';
import { basesFor } from '../loot/bases';
import { clampLevel, generateItem, hashSeed, pickWeighted } from '../loot/generate';
import { RARITIES, rarity, rarityCeiling, type RarityId, rollGated } from '../loot/rarity';
import type { Category, ItemInstance } from '../loot/types';
import { getTier, lootLevel, MAX_RIFT_LEVEL } from '../progression/tiers';
import { MARKET } from './config';
import { lockedCategoriesOf, lockedFamiliesOf } from '../progression/unlocks';

/**
 * Merchant stock (pure). Stock is generated by the same item generator as enemy loot,
 * from a deterministic seed (profile + rotation), and stored in the save: reopening a
 * terminal never rerolls it. A new rotation happens after every completed run, or when
 * the player pays for a manual refresh.
 */
export type MerchantId = 'equipment' | 'modules';

export interface MarketEntry {
  /** Stable entry id within a rotation (purchase target). */
  id: string;
  item: ItemInstance;
  sold: boolean;
  /** Featured slot: better rarity floor. */
  featured: boolean;
}

export interface ExchangeOffer {
  id: string;
  /** Packs left this rotation. */
  left: number;
}

export interface MarketState {
  /** Increments on every refresh; part of every generated uid. */
  rotation: number;
  generatedAt: number;
  /** Manual refreshes bought during the current rotation (escalating cost). */
  refreshes: number;
  equipment: MarketEntry[];
  modules: MarketEntry[];
  exchange: ExchangeOffer[];
}

/** Inputs that decide stock quality (derived from the save). */
export interface MarketProgress {
  /** Typical item level the player is finding (see progressLevel). */
  level: number;
  /** Highest unlocked Rift Level. */
  tier: number;
  /** M7: extra equipment slots from HQ facilities (Market Uplink). */
  extra?: number;
  /** Staged-unlock loot locks: merchants never stock locked categories or weapon families. */
  locks?: readonly string[];
}

/**
 * Level of loot the player currently earns: the best item level any Rift Level record reached (`lootLevel` of its
 * best cleared wave), at least the unlocked level's base. Merchants and fabrication work at this level, so they
 * keep pace with progression without outpacing drops.
 */
export function progressLevel(records: Record<string, { bestWave: number }>, unlocked: number): number {
  let lvl = getTier(Math.max(1, unlocked)).lootLevelBonus;
  for (const [id, r] of Object.entries(records)) {
    const t = Number(id);
    if (Number.isInteger(t) && t >= 1 && r) lvl = Math.max(lvl, lootLevel(getTier(t), r.bestWave));
  }
  return clampLevel(lvl);
}

const EQUIPMENT_WEIGHTS: Partial<Record<Category, number>> = { weapon: 3, armor: 2, shield: 2, reactor: 1.5, processor: 1.5, accessory: 1.5, ability: 1.4, ultimate: 0.7 };

/**
 * Merchant rarity: the Rift Level's gate (never above what the player's own drops can be) and the merchant cap (epic);
 * the featured slot may hold a legendary from `MARKET.featuredLegendaryAt`.
 */
function cap(id: RarityId, rl: number, featured: boolean): RarityId {
  const top = featured && rl >= MARKET.featuredLegendaryAt ? 'legendary' : MARKET.maxRarity;
  const gate = rarityCeiling(rl);
  const max = Math.min(rarity(top).index, rarity(gate).index);
  return rarity(id).index > max ? RARITIES[max].id : id;
}

function pickCategory(rand: () => number, locked: readonly Category[] = []): Category {
  const entries = (Object.entries(EQUIPMENT_WEIGHTS) as [Category, number][]).filter(([c]) => !locked.includes(c));
  return pickWeighted(entries, ([, w]) => w, rand)![0];
}

export function marketSeed(profileId: string, rotation: number): number {
  return hashSeed(`market|${profileId}|${rotation}`);
}

/** Generate a full rotation of stock. Same (profile, rotation, progress) -> same stock. */
export function generateMarket(profileId: string, rotation: number, progress: MarketProgress, now = Date.now()): MarketState {
  const rand = mulberry32(marketSeed(profileId, rotation));
  const tier = getTier(Math.max(1, Math.min(MAX_RIFT_LEVEL, progress.tier)));
  const luckT = tier.lootLuck;
  const level = () => clampLevel(progress.level - 1 + Math.floor(rand() * 3));
  const families = lockedFamiliesOf(progress.locks);
  const lockedCats = lockedCategoriesOf(progress.locks);
  const make = (kind: MerchantId, i: number, category: Category, rar: RarityId): MarketEntry => {
    const id = `mk${rotation}_${kind[0]}${i}`;
    const item = generateItem({ uid: `${id}_${profileId.slice(-6)}`, seed: Math.floor(rand() * 4294967296) >>> 0, level: level(), rarity: rar, category, source: 'merchant', now, excludeFamilies: families });
    return { id, item, sold: false, featured: false };
  };
  const equipment: MarketEntry[] = [];
  for (let i = 0; i < MARKET.equipmentSlots + Math.max(0, Math.min(4, progress.extra ?? 0)); i++) {
    const featured = i === 0;
    const rar = cap(rollGated(rand, tier.id, MARKET.equipmentLuck * luckT, featured ? 'rare' : 'common', featured ? 2 : 0), tier.id, featured);
    const e = make('equipment', i, pickCategory(rand, lockedCats), rar);
    e.featured = featured;
    equipment.push(e);
  }
  const modules: MarketEntry[] = [];
  const moduleBases = basesFor('module');
  // Modules are a staged unlock: no broker stock until the warden can use them.
  for (let i = 0; i < (lockedCats.includes('module') ? 0 : MARKET.moduleSlots); i++) {
    const featured = i === 0;
    const rar = cap(rollGated(rand, tier.id, MARKET.moduleLuck * luckT, featured ? 'rare' : 'uncommon', featured ? 2 : 0), tier.id, false);
    const base = pickWeighted(moduleBases, (b) => b.weight, rand)!;
    const id = `mk${rotation}_m${i}`;
    const item = generateItem({ uid: `${id}_${profileId.slice(-6)}`, seed: Math.floor(rand() * 4294967296) >>> 0, level: level(), rarity: rar, baseId: base.id, source: 'merchant', now });
    modules.push({ id, item, sold: false, featured });
  }
  const exchange = MARKET.exchange.map((o) => ({ id: o.id, left: o.stock + (o.id === 'component_cell' ? Math.max(0, tier.id - 1) : 0) }));
  return { rotation, generatedAt: now, refreshes: 0, equipment, modules, exchange };
}

export function merchantEntries(m: MarketState, merchant: MerchantId): MarketEntry[] {
  return merchant === 'equipment' ? m.equipment : m.modules;
}
